package com.badrulamin.University_Management.repository;  import com.badrulamin.University_Management.entity.AdmissionOfferLetter; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository;  import java.util.List; import java.util.Optional;  @Repository public interface AdmissionOfferLetterRepository extends JpaRepository<AdmissionOfferLetter, Long> {     Page<AdmissionOfferLetter> findByStatus(String status, Pageable pageable);     List<AdmissionOfferLetter> findByApplication_Id(Long applicationId);     Optional<AdmissionOfferLetter> findByLetterNumber(String letterNumber);     long countByStatus(String status); }